// Databron 1: verwerkte facturen (input van deze node)
const facturen = $input.all().map(i => i.json);

// Databron 2: validatiefouten (apart opgehaald). Veilig ophalen — als het
// tabblad leeg is of niet bestaat, ga dan door met een lege lijst.
let fouten = [];
try {
  fouten = $('Haal fouten op').all().map(i => i.json);
} catch (e) {
  fouten = [];
}

function num(v) {
  if (v == null || v === '') return 0;
  if (typeof v === 'number') return v;
  let s = String(v).trim();
  if (s.includes(',') && s.includes('.')) s = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',')) s = s.replace(',', '.');
  const n = parseFloat(s.replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
}

const totaal = facturen.length;
let pass = 0, review = 0, fatal = 0;
let totaalBedrag = 0, totaalBtw = 0, totaalBetaalbaar = 0;
const leveranciers = new Set();

// Per leverancier bijhouden voor de "heatmap" (KPI 2-benadering)
const perLeverancier = {};   // naam -> { totaal, afwijkend }

for (const f of facturen) {
  const res = String(f.validatieResultaat || '').toUpperCase();
  if (res === 'PASS') pass++;
  else if (res === 'REVIEW') review++;
  else if (res === 'FATAL') fatal++;

  totaalBedrag     += num(f.totaalbedrag);
  totaalBtw        += num(f.btwbedrag);
  totaalBetaalbaar += num(f.betaalbaarBedrag);

  const lev = f.leveranciernaam || 'Onbekend';
  leveranciers.add(lev);
  if (!perLeverancier[lev]) perLeverancier[lev] = { totaal: 0, afwijkend: 0 };
  perLeverancier[lev].totaal++;
  if (res === 'REVIEW' || res === 'FATAL') perLeverancier[lev].afwijkend++;
}

// KPI 1: percentage handmatige handelingen (REVIEW + FATAL)
const handmatigPct = totaal > 0 ? Math.round(((review + fatal) / totaal) * 100) : 0;
const stpPct = 100 - handmatigPct;          // Straight Through Processing
const doelHandmatig = 40;                    // doelstelling uit het verslag
const doelGehaald = handmatigPct <= doelHandmatig;

// KPI 2: afwijkingspercentage per leverancier (heatmap), gesorteerd hoog->laag
const heatmap = Object.entries(perLeverancier).map(([naam, d]) => ({
  naam,
  totaal: d.totaal,
  afwijkend: d.afwijkend,
  pct: d.totaal > 0 ? Math.round((d.afwijkend / d.totaal) * 100) : 0
})).sort((a, b) => b.pct - a.pct).slice(0, 8);

// KPI 3: top-5 meest voorkomende fouten (uit Validatiefouten-sheet)
const foutTeller = {};
for (const fo of fouten) {
  const code = fo.foutcode || 'onbekend';
  const oms  = fo.omschrijving || '';
  if (!foutTeller[code]) foutTeller[code] = { code, aantal: 0, voorbeeld: oms };
  foutTeller[code].aantal++;
}
const topFouten = Object.values(foutTeller)
  .sort((a, b) => b.aantal - a.aantal)
  .slice(0, 5);

// Recente facturen (laatste 15, nieuwste eerst)
const recente = facturen.slice(-15).reverse().map(f => ({
  factuurnummer:      f.factuurnummer || '-',
  leveranciernaam:    f.leveranciernaam || '-',
  factuurdatum:       f.factuurdatum || '-',
  totaalbedrag:       num(f.totaalbedrag),
  validatieResultaat: String(f.validatieResultaat || 'onbekend').toUpperCase()
}));

return [{ json: {
  aantalFacturen: totaal, aantalPass: pass, aantalReview: review, aantalFatal: fatal,
  totaalBedrag, totaalBtw, totaalBetaalbaar, aantalLeveranciers: leveranciers.size,
  handmatigPct, stpPct, doelHandmatig, doelGehaald,
  heatmap, topFouten, recenteFacturen: recente
} }];
